draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('?', W/2, H/2);
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 50 + 30*Math.sin(t), H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 50 - 30*Math.sin(t), H/2 + 100);
  ctx.stroke();
  ctx.font = '18px Arial';
  ctx.fillText('Assumption', W/2 + 50 + 30*Math.sin(t), H/2 + 120);
  ctx.fillText('Question', W/2 - 50 - 30*Math.sin(t), H/2 + 120);
  ctx.restore();
}
